'use client';

import { useScroll } from 'motion/react';
import { type RefObject, useRef } from 'react';

import { ArrowRightIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

import { HERO } from './data';
import { ProductView } from './product-view';
import { TiltFrame } from './tilt-frame';

export type Heroes05Props = {
  /** The element that scrolls the page when it is not the window, such as a preview frame of your own. */
  scrollContainerRef?: RefObject<HTMLElement | null>;
};

export default function Heroes05({ scrollContainerRef }: Heroes05Props) {
  const sectionRef = useRef<HTMLElement>(null);
  /** Tilted while the top of the hero meets the top of the page, flat once the page scrolled 240px past it. */
  const { scrollYProgress } = useScroll({
    target: sectionRef,
    container: scrollContainerRef,
    offset: ['start start', '240px start'],
  });

  return (
    <section ref={sectionRef} className='@container overflow-x-clip'>
      <div className='mx-auto flex max-w-6xl flex-col items-center px-4 py-16 @2xl:px-6 @2xl:py-24'>
        <div className='flex max-w-3xl flex-col items-center gap-5 text-center'>
          <p className='text-primary-ink text-sm font-medium'>{HERO.eyebrow}</p>
          <h1 className='text-4xl font-semibold text-balance @2xl:text-5xl'>
            {HERO.title}
          </h1>
          <p className='text-muted-foreground max-w-xl text-base text-pretty'>
            {HERO.description}
          </p>
          <div className='flex flex-wrap justify-center gap-2 pt-1'>
            <Button size='lg' nativeButton={false} render={<a href='#' />}>
              {HERO.primaryAction}
              <ArrowRightIcon />
            </Button>
            <Button
              size='lg'
              variant='outline'
              nativeButton={false}
              render={<a href='#' />}
            >
              {HERO.secondaryAction}
            </Button>
          </div>
        </div>
        <div className='mt-12 w-full max-w-5xl @2xl:mt-16'>
          <TiltFrame progress={scrollYProgress}>
            <ProductView />
          </TiltFrame>
        </div>
      </div>
    </section>
  );
}

'use client';

import { motion, type MotionValue, useTransform } from 'motion/react';
import type { ReactNode } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

/** Enough to read as a screen leaning back; with the scale, its near edge never gets wider than the page. */
const TILT_DEGREES = 16;

const TILT_SCALE = 0.9;

const FLAT = { rotateX: 0, scale: 1 };

type Tilt = {
  rotateX: MotionValue<number>;
  scale: MotionValue<number>;
};

function styleOf(shouldReduceMotion: boolean, tilt: Tilt) {
  if (shouldReduceMotion) {
    return FLAT;
  }
  return tilt;
}

type TiltFrameProps = {
  /** From 0 at the top of the hero to 1 once the page scrolled past the stretch that flattens it. */
  progress: MotionValue<number>;
  children: ReactNode;
};

/**
 * Holds the product view tilted back in 3D and lays it flat as the progress runs. The values are
 * written to the element by the animation library, so a scroll never renders the view again.
 */
export function TiltFrame({ progress, children }: TiltFrameProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const rotateX = useTransform(progress, [0, 1], [TILT_DEGREES, 0]);
  const scale = useTransform(progress, [0, 1], [TILT_SCALE, 1]);
  const tilt: Tilt = { rotateX, scale };
  const style = styleOf(shouldReduceMotion, tilt);

  return (
    <div className='[perspective:1600px]'>
      <motion.div style={style} className='origin-top'>
        {children}
      </motion.div>
    </div>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import {
  type AutoplayStep,
  useAutoplay,
} from '@/registry/ndeko/hooks/use-autoplay';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  ArrowUpIcon,
  BookOpenIcon,
  type Icon,
  InboxIcon,
  MessageSquareIcon,
  RouteIcon,
  UsersIcon,
} from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { countOf } from '@/registry/ndeko/lib/words';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { Chip } from '@/registry/ndeko/ui/chip';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';

import {
  ARRIVING,
  type FeatureRequest,
  FILTERS,
  NAV,
  type NavItem,
  REQUESTS,
  type RequestStatus,
  WORKSPACE,
} from './data';

type StatusLook = {
  label: string;
  color: string;
};

const STATUS: Record<RequestStatus, StatusLook> = {
  open: { label: 'Open', color: 'var(--muted-foreground)' },
  planned: { label: 'Planned', color: 'var(--info)' },
  building: { label: 'In progress', color: 'var(--warning)' },
  shipped: { label: 'Shipped', color: 'var(--success)' },
};

const NAV_ICONS: Record<NavItem['id'], Icon> = {
  inbox: InboxIcon,
  requests: MessageSquareIcon,
  roadmap: RouteIcon,
  changelog: BookOpenIcon,
  customers: UsersIcon,
};

const ACTIVE_NAV: NavItem['id'] = 'requests';

const LOOP_AFTER_MS = 3200;

function askedByOf(request: FeatureRequest) {
  if (request.others === 0) {
    return request.company;
  }
  const others = countOf(request.others, 'other');
  return `${request.company} and ${others}`;
}

function withArrival(requests: FeatureRequest[]) {
  const isHere = requests.some((request) => request.id === ARRIVING.id);
  if (isHere) {
    return requests;
  }
  return [ARRIVING, ...requests];
}

/** A vote is one more customer asking, so the line of who asked counts them too. */
function withVote(requests: FeatureRequest[], id: string) {
  return requests.map((request) => {
    if (request.id !== id) {
      return request;
    }
    const votes = request.votes + 1;
    const others = request.others + 1;
    return { ...request, votes, others };
  });
}

function withStatus(
  requests: FeatureRequest[],
  id: string,
  status: RequestStatus
) {
  return requests.map((request) => {
    if (request.id !== id) {
      return request;
    }
    return { ...request, status };
  });
}

function NavRow({ item }: { item: NavItem }) {
  const Glyph = NAV_ICONS[item.id];
  const isActive = item.id === ACTIVE_NAV;
  const hasCount = item.count !== undefined;

  return (
    <li
      className={cn(
        'text-muted-foreground flex h-7 items-center gap-2 rounded-md px-2 text-[13px]',
        isActive && 'bg-foreground/[0.06] text-foreground'
      )}
    >
      <Glyph className='size-4 shrink-0' />
      <span className='min-w-0 flex-1 truncate'>{item.label}</span>
      {hasCount && <span className='text-xs tabular-nums'>{item.count}</span>}
    </li>
  );
}

function Sidebar() {
  return (
    <div className='hidden w-44 shrink-0 flex-col gap-4 p-2 @2xl:flex'>
      <div className='flex items-center gap-2 px-1.5 pt-1'>
        <CompanyMark seed={WORKSPACE} />
        <span className='truncate text-[13px] font-medium'>{WORKSPACE}</span>
      </div>
      <ul className='flex flex-col gap-0.5'>
        {NAV.map((item) => (
          <NavRow key={item.id} item={item} />
        ))}
      </ul>
    </div>
  );
}

function filterLookOf(index: number) {
  if (index === 0) {
    return 'bg-card text-foreground shadow-[0_1px_2px_rgb(0_0_0/0.08)] dark:bg-foreground/[0.09]';
  }
  return 'text-muted-foreground';
}

function ListHeader({ count }: { count: number }) {
  return (
    <div className='flex items-center gap-2 px-4 pt-3.5 pb-2'>
      <span className='text-sm font-medium'>Requests</span>
      <MotionNumber value={count} className='text-muted-foreground text-xs' />
      <span className='bg-foreground/[0.05] ms-auto hidden rounded-lg p-0.5 @md:flex'>
        {FILTERS.map((filter, index) => (
          <span
            key={filter}
            className={cn(
              'rounded-md px-2.5 py-0.5 text-xs',
              filterLookOf(index)
            )}
          >
            {filter}
          </span>
        ))}
      </span>
    </div>
  );
}

function RequestRow({ request }: { request: FeatureRequest }) {
  const status = STATUS[request.status];
  const askedBy = askedByOf(request);

  return (
    <div className='flex items-center gap-3 rounded-lg px-2 py-2'>
      <span className='keycap-3d flex w-10 shrink-0 flex-col items-center gap-0.5 rounded-lg py-1'>
        <ArrowUpIcon className='text-muted-foreground size-3' />
        <MotionNumber value={request.votes} className='text-xs font-medium' />
      </span>
      <span className='flex min-w-0 flex-1 flex-col gap-0.5'>
        <span className='truncate text-[13px] font-medium'>
          {request.title}
        </span>
        <span className='text-muted-foreground flex min-w-0 items-center gap-1.5 text-xs'>
          <CompanyMark seed={request.company} size='sm' />
          <span className='truncate'>{askedBy}</span>
        </span>
      </span>
      <Swap swapKey={request.status} className='shrink-0'>
        <Chip color={status.color}>{status.label}</Chip>
      </Swap>
    </div>
  );
}

/**
 * The app the hero sells, drawn with the look of our blocks and playing on its own: a request
 * arrives at the top, a vote lands and one request ships. It is a picture, so nothing in it is
 * reachable; the first click on it ends the demonstration.
 */
export function ProductView() {
  const [requests, setRequests] = useState<FeatureRequest[]>(REQUESTS);
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = rowPresenceOf(shouldReduceMotion);

  function startOver() {
    setRequests(REQUESTS);
  }

  const steps: AutoplayStep[] = [
    { after: 1800, run: () => setRequests(withArrival) },
    {
      after: 1500,
      run: () => setRequests((current) => withVote(current, 'csv')),
    },
    {
      after: 1600,
      run: () =>
        setRequests((current) => withStatus(current, 'dark', 'shipped')),
    },
    {
      after: 1500,
      run: () => setRequests((current) => withVote(current, ARRIVING.id)),
    },
  ];
  const { ref } = useAutoplay(steps, {
    loopAfter: LOOP_AFTER_MS,
    onReset: startOver,
  });

  return (
    <div ref={ref} className='@container'>
      <div
        inert
        aria-hidden='true'
        className='bg-foreground/[0.025] flex gap-2 rounded-2xl p-2 select-none'
      >
        <Sidebar />
        <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex min-w-0 flex-1 flex-col rounded-[calc(var(--radius-2xl)-0.5rem)] shadow-[0_1px_2px_rgb(0_0_0/0.04),0_12px_32px_-16px_rgb(0_0_0/0.12)]'>
          <ListHeader count={requests.length} />
          <ul className='h-[19rem] overflow-hidden mask-b-from-75% px-2 pb-2'>
            <AnimatePresence initial={false}>
              {requests.map((request) => (
                <motion.li
                  key={request.id}
                  {...presence}
                  className='overflow-hidden'
                >
                  <RequestRow request={request} />
                </motion.li>
              ))}
            </AnimatePresence>
          </ul>
        </div>
      </div>
    </div>
  );
}

export type RequestStatus = 'open' | 'planned' | 'building' | 'shipped';

export type FeatureRequest = {
  id: string;
  title: string;
  /** The customer who asked first; the others who asked are counted. */
  company: string;
  others: number;
  votes: number;
  status: RequestStatus;
};

export type NavItem = {
  id: 'inbox' | 'requests' | 'roadmap' | 'changelog' | 'customers';
  label: string;
  count?: number;
};

export const HERO = {
  eyebrow: 'Feedback, roadmap and changelog in one place',
  title: 'Hear every customer, then ship what they asked for',
  description:
    'Requests from email, chat and calls land in one list, ranked by how many customers asked. Mark one shipped and everyone who asked hears about it.',
  primaryAction: 'Start for free',
  secondaryAction: 'Book a demo',
};

export const WORKSPACE = 'Harbor & Pine';

export const NAV: NavItem[] = [
  { id: 'inbox', label: 'Inbox', count: 12 },
  { id: 'requests', label: 'Requests' },
  { id: 'roadmap', label: 'Roadmap' },
  { id: 'changelog', label: 'Changelog' },
  { id: 'customers', label: 'Customers' },
];

export const FILTERS = ['Open', 'Planned', 'Shipped'];

export const REQUESTS: FeatureRequest[] = [
  {
    id: 'csv',
    title: 'Export reports to CSV',
    company: 'Lumen Labs',
    others: 47,
    votes: 48,
    status: 'planned',
  },
  {
    id: 'dark',
    title: 'Dark mode for the dashboard',
    company: 'Northwind Atelier',
    others: 40,
    votes: 41,
    status: 'building',
  },
  {
    id: 'key',
    title: 'Sign in with a security key',
    company: 'Brightwater Clinic',
    others: 32,
    votes: 33,
    status: 'planned',
  },
  {
    id: 'tags',
    title: 'Edit the tags of many requests at once',
    company: 'Copperfield and Co',
    others: 26,
    votes: 27,
    status: 'open',
  },
  {
    id: 'digest',
    title: 'A weekly digest by email',
    company: 'Sable Studio',
    others: 1,
    votes: 2,
    status: 'open',
  },
];

/** The request the demonstration brings in at the top of the list. */
export const ARRIVING: FeatureRequest = {
  id: 'share',
  title: 'Share a saved view with a link',
  company: 'Pinecone Bakery',
  others: 0,
  votes: 1,
  status: 'open',
};
